CREATE DATABASE IF NOT EXISTS logistic_world CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE logistic_world;
CREATE TABLE paises(id BIGINT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL,codigo_iso CHAR(2) UNIQUE NOT NULL,continente VARCHAR(50) NOT NULL,moneda VARCHAR(10) NOT NULL);
CREATE TABLE clientes(id BIGINT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(150) NOT NULL,documento VARCHAR(30) UNIQUE NOT NULL,telefono VARCHAR(30),correo VARCHAR(150) UNIQUE);
CREATE TABLE transportistas(id BIGINT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(150) NOT NULL,nit VARCHAR(30) UNIQUE NOT NULL,telefono VARCHAR(30),correo VARCHAR(150));
CREATE TABLE vehiculos(id BIGINT AUTO_INCREMENT PRIMARY KEY,placa VARCHAR(20) UNIQUE NOT NULL,tipo ENUM('CAMION','FURGON','TRACTOCAMION','AVION','BARCO','MOTO') NOT NULL,capacidad_kg DECIMAL(12,2) NOT NULL,estado ENUM('DISPONIBLE','EN_RUTA','MANTENIMIENTO') DEFAULT 'DISPONIBLE',transportista_id BIGINT,FOREIGN KEY(transportista_id) REFERENCES transportistas(id));
CREATE TABLE rutas(id BIGINT AUTO_INCREMENT PRIMARY KEY,origen VARCHAR(150) NOT NULL,destino VARCHAR(150) NOT NULL,distancia_km DECIMAL(12,2),duracion_estimada_horas DECIMAL(8,2),pais_origen_id BIGINT,pais_destino_id BIGINT,FOREIGN KEY(pais_origen_id) REFERENCES paises(id),FOREIGN KEY(pais_destino_id) REFERENCES paises(id));
CREATE TABLE categorias_carga(id BIGINT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) UNIQUE NOT NULL,descripcion VARCHAR(255),requiere_refrigeracion BOOLEAN DEFAULT FALSE,requiere_cuidado_especial BOOLEAN DEFAULT FALSE);
CREATE TABLE envios(id BIGINT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(30) UNIQUE NOT NULL,descripcion VARCHAR(255) NOT NULL,peso_kg DECIMAL(12,2) NOT NULL,estado ENUM('PENDIENTE','RECOGIDO','EN_TRANSITO','ENTREGADO','CANCELADO') DEFAULT 'PENDIENTE',fecha_registro DATETIME DEFAULT CURRENT_TIMESTAMP,fecha_entrega_estimada DATE,cliente_id BIGINT NOT NULL,ruta_id BIGINT,vehiculo_id BIGINT,categoria_id BIGINT,FOREIGN KEY(cliente_id) REFERENCES clientes(id),FOREIGN KEY(ruta_id) REFERENCES rutas(id),FOREIGN KEY(vehiculo_id) REFERENCES vehiculos(id),FOREIGN KEY(categoria_id) REFERENCES categorias_carga(id));
CREATE TABLE seguimiento_envios(id BIGINT AUTO_INCREMENT PRIMARY KEY,envio_id BIGINT NOT NULL,ubicacion VARCHAR(180) NOT NULL,estado VARCHAR(60) NOT NULL,observacion VARCHAR(255),fecha_evento DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(envio_id) REFERENCES envios(id) ON DELETE CASCADE);
